import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
import os

os.environ["CXX"] = "hipcc"

cpp_source = """
#include <hip/hip_runtime.h>
#include <cmath>

__global__ void fused_pool_activation_kernel(
    const float* __restrict__ input,
    const float* __restrict__ bias,
    float* __restrict__ output,
    float scaling,
    int N, int C, int H_in, int W_in,
    int H_out, int W_out,
    int pool_k, int pool_stride) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = N * C * H_out * W_out;

    if (idx >= total_elements) return;

    // Decode index
    // Layout is N, C, H_out, W_out (contiguous)
    int w_out = idx % W_out;
    int tmp = idx / W_out;
    int h_out = tmp % H_out;
    tmp = tmp / H_out;
    int c = tmp % C;
    int n = tmp / C;

    int h_start = h_out * pool_stride;
    int w_start = w_out * pool_stride;

    // Determine the base pointer for this (n, c) slice
    // input is (N, C, H_in, W_in)
    // We can precompute channel offset: n * C * H_in * W_in + c * H_in * W_in
    // Optimization: stride_n = C * H_in * W_in
    // stride_c = H_in * W_in

    const float* input_slice = input + (n * C + c) * (H_in * W_in);

    float max_val = -1e38f; // -inf

    for (int i = 0; i < pool_k; ++i) {
        int r = h_start + i;
        for (int j = 0; j < pool_k; ++j) {
            int c_in = w_start + j;
            float val = input_slice[r * W_in + c_in];
            if (val > max_val) {
                max_val = val;
            }
        }
    }

    // Apply Tanh -> Scale -> Bias
    // tanh is monotonic, scale (2.0) is positive, bias is additive
    // So max(f(x)) == f(max(x))

    float res = tanhf(max_val);
    res = res * scaling;
    res = res + bias[c]; 

    output[idx] = res;
}

torch::Tensor fused_forward(torch::Tensor input, torch::Tensor bias, float scaling, 
                           int kernel_size, int stride) {
    // Input is (N, C, H_in, W_in)
    int N = input.size(0);
    int C = input.size(1);
    int H_in = input.size(2);
    int W_in = input.size(3);

    // Calculate output dimensions
    // Pad=0, Dilation=1, Ceil_mode=False (default for MaxPool2d)
    int H_out = (H_in - kernel_size) / stride + 1;
    int W_out = (W_in - kernel_size) / stride + 1;

    auto options = torch::TensorOptions().dtype(input.dtype()).device(input.device());
    auto output = torch::empty({N, C, H_out, W_out}, options);

    int total_elements = N * C * H_out * W_out;
    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    fused_pool_activation_kernel<<<num_blocks, block_size, 0, at::cuda::getCurrentCUDAStream()>>>(
        input.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        scaling,
        N, C, H_in, W_in,
        H_out, W_out,
        kernel_size, stride
    );

    return output;
}
"""

fused_ops = load_inline(
    name="fused_ops_v1",
    cpp_sources=cpp_source,
    functions=["fused_forward"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, scaling_factor, bias_shape, pool_kernel_size):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.scaling_factor = scaling_factor
        self.bias = nn.Parameter(torch.randn(bias_shape))
        # We store pool params
        self.pool_kernel_size = pool_kernel_size
        self.pool_stride = pool_kernel_size # Default stride is kernel_size
        self.fused_ops = fused_ops

    def forward(self, x):
        # Convolution
        x = self.conv(x)
        # Fused Tanh, Scale, Bias, MaxPool
        # Note: We exploit the mathematical property that max(tanh(x)*s+b) == tanh(max(x))*s+b for s>0
        # So we perform MaxPool first (fused), then apply activation/scale/bias scalar-wise.
        # But in our kernel, we do it all in one go reading from Conv output.

        # Ensure contiguous output from conv for the kernel (usually is, but for safety)
        if not x.is_contiguous():
            x = x.contiguous()

        return self.fused_ops.fused_forward(
            x, 
            self.bias.view(-1).contiguous(), 
            self.scaling_factor, 
            self.pool_kernel_size, 
            self.pool_stride
        )

